CREATE OR REPLACE FUNCTION public.fn_get_experience_session_by_id(p_tenant_id uuid, p_session_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, experience_id uuid, experience_schedule_id uuid, classroom_id uuid, session_date date, start_time time without time zone, end_time time without time zone, status character varying, primary_teacher_id uuid, actual_notes text, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT es.id, es.tenant_id, es.experience_id,             es.experience_schedule_id, es.classroom_id,             es.session_date, es.start_time, es.end_time,             es.status, es.primary_teacher_id, es.actual_notes,             es.created_at, es.updated_at     FROM experience_sessions es     WHERE es.id = p_session_id AND es.tenant_id = p_tenant_id; END; $function$ ;
